export async function answer(
  question: string,
  tenant: TenantContext,
): Promise<Answer> {
  const candidates = await hybridSearch(question, {
    tenantId: tenant.id,
    // The filter is an argument to the search, not a step after it. Filtering a
    // ranked list post hoc still leaks that unreadable documents exist.
    visibleTo: tenant.roles,
    limit: 40,
  });

  const passages = await rerank(question, candidates, { keep: 8 });
  if (passages.length === 0) {
    return { kind: "no-answer", reason: "no-passages" };
  }

  return {
    kind: "answer",
    text: await compose(question, passages),
    citations: passages.map((passage) => passage.citation),
  };
}

from dataclasses import dataclass


@dataclass(frozen=True)
class Passage:
    document_id: str
    ordinal: int
    lexical_rank: int
    vector_rank: int


def reciprocal_rank_fusion(
    lexical: list[Passage],
    vector: list[Passage],
    k: int = 60,
) -> list[Passage]:
    """Merge two ranked lists without needing their scores to be comparable."""
    scores: dict[tuple[str, int], float] = {}
    for ranked in (lexical, vector):
        for position, passage in enumerate(ranked, start=1):
            key = (passage.document_id, passage.ordinal)
            scores[key] = scores.get(key, 0.0) + 1.0 / (k + position)

    by_key = {(p.document_id, p.ordinal): p for p in (*lexical, *vector)}
    return [by_key[key] for key in sorted(scores, key=scores.__getitem__, reverse=True)]

-- Row-level security is the whole answer to multi-tenancy here: the application
-- cannot forget the tenant filter, because the database applies it.
ALTER TABLE passage ENABLE ROW LEVEL SECURITY;

CREATE POLICY passage_tenant_isolation ON passage USING (tenant_id = current_setting('app.tenant_id')::uuid);

-- The retrieval query itself, on one line because that is the shape a generated query has.
SELECT p.id, p.document_id, p.ordinal, p.body, ts_rank_cd(p.search_vector, websearch_to_tsquery('english', $1)) AS lexical_score, 1 - (p.embedding <=> $2::vector) AS vector_score FROM passage AS p JOIN document AS d ON d.id = p.document_id WHERE d.classification = ANY($3::text[]) AND d.retired_at IS NULL ORDER BY lexical_score DESC, vector_score DESC LIMIT 40;
